"use client";

import { useState, useEffect, useMemo, type ReactNode } from "react";
import { Menu, X } from "lucide-react";
import { ThemeToggle } from "../primitives/theme-toggle";
import { useYunUI } from "../adapters/context";

export interface NavLink {
    /** Destination href (supports `/#section` anchors for scroll-spy on the home page). */
    href: string;
    /** Link text. */
    label: string;
}

interface NavbarProps {
    /** Brand name shown next to the logo. */
    appName: string;
    /** Logo image src (default: /favicon.ico). */
    logoSrc?: string;
    /** Center navigation links. The host builds these from branding/flags/i18n. */
    links?: NavLink[];
    /** Current route, used for active-link + scroll-spy. @defaultValue "/" */
    currentPath?: string;
    /** `public` (full nav + auth) or `minimal` (no links/auth). @defaultValue "public" */
    variant?: "public" | "minimal";
    /** Localized auth labels. */
    labels?: { signIn?: string; signUp?: string; menu?: string };
    /** Right-side control slots; the host injects the configured switcher. */
    languageSwitcher?: ReactNode;
    /** Defaults to YunUI's ThemeToggle. */
    themeToggle?: ReactNode;
    /** Where the logo links to. @defaultValue "/" */
    homeHref?: string;
    /** Sign-in link destination. @defaultValue "/login" */
    loginHref?: string;
    /** Sign-up link destination. @defaultValue "/signup" */
    signupHref?: string;
    /**
     * Signed-in account control — pass an `AccountMenu`. When present it
     * REPLACES the sign in / sign up buttons (desktop and mobile), so a reader
     * who is already signed in sees their avatar rather than an invitation to
     * sign in again.
     */
    account?: ReactNode;
    /**
     * Replaces the logo + wordmark block entirely. Pass a mark-only logo, a
     * custom lockup, anything — it is still wrapped in the link to `homeHref`.
     * Without this, a brand that is a single glyph had to be faked through
     * `logoSrc`/`appName`, which is why YunUI's own site and YunNEWS each kept
     * a private copy of this bar.
     */
    brand?: ReactNode;
    /**
     * Extra controls in the right-hand cluster, before the language/theme
     * pills — a GitHub link, a search button. Desktop only, matching the rest
     * of that cluster; put the mobile equivalent in `mobileMenuHeader`.
     */
    actions?: ReactNode;
    /** Rendered at the TOP of the mobile menu, above the links. */
    mobileMenuHeader?: ReactNode;
    /**
     * The bottom region of the mobile menu, under the divider. Passing this
     * REPLACES the automatic `languageSwitcher` row there — so a host that
     * wants the language pill alongside something else (a GitHub link, a
     * status chip) lays that row out itself instead of getting two rows.
     * Leave it off and the language row appears on its own, as before.
     */
    mobileMenuFooter?: ReactNode;
    /**
     * Accessible name for the `<nav>` landmark. A page with more than one nav
     * needs each one named, or a screen reader offers several identical
     * "navigation" regions.
     */
    label?: string;
    /** Extra classes on the `<nav>` element. */
    className?: string;
}

/** Floating top navigation bar: logo, center links with scroll-spy, theme/language slots, and auth buttons with a mobile menu. */
export function Navbar({
    appName,
    logoSrc = "/favicon.ico",
    links = [],
    currentPath = "/",
    variant = "public",
    labels,
    languageSwitcher,
    themeToggle,
    homeHref = "/",
    loginHref = "/login",
    signupHref = "/signup",
    account,
    brand,
    actions,
    mobileMenuHeader,
    mobileMenuFooter,
    label,
    className,
}: NavbarProps) {
    const { Link, Image } = useYunUI();
    const [scrollSection, setScrollSection] = useState<string>("");
    const [menuOpen, setMenuOpen] = useState(false);

    const signIn = labels?.signIn ?? "Sign In";
    const signUp = labels?.signUp ?? "Sign Up";
    const menuLabel = labels?.menu ?? "Menu";

    // Clear scroll tracking when not on home page
    const activeSection = useMemo(() => {
        return currentPath === "/" ? scrollSection : "";
    }, [currentPath, scrollSection]);

    // Set up scroll tracking only on home page
    useEffect(() => {
        if (currentPath !== "/") return;

        const sections = document.querySelectorAll("section[id]");
        if (sections.length === 0) return;

        const handleScroll = () => {
            const scrollPosition = window.scrollY + 150; // Offset for fixed navbar

            let currentSection = "";
            sections.forEach((section) => {
                const sectionTop = (section as HTMLElement).offsetTop;
                const sectionHeight = (section as HTMLElement).offsetHeight;

                if (scrollPosition >= sectionTop && scrollPosition < sectionTop + sectionHeight) {
                    currentSection = `#${section.id}`;
                }
            });

            setScrollSection(currentSection);
        };

        handleScroll();

        let ticking = false;
        const onScroll = () => {
            if (!ticking) {
                window.requestAnimationFrame(() => {
                    handleScroll();
                    ticking = false;
                });
                ticking = true;
            }
        };

        window.addEventListener("scroll", onScroll, { passive: true });
        return () => window.removeEventListener("scroll", onScroll);
    }, [currentPath]);

    const isActive = (path: string) => {
        if (currentPath === path) return true;
        if (path.startsWith("/#")) {
            return currentPath === "/" && activeSection === path.slice(1);
        }
        return false;
    };

    return (
        <nav
            style={{ top: "max(1.5rem, env(safe-area-inset-top))" }}
            /* Centered with inset-x-0 + mx-auto, NOT -translate-x-1/2: a transformed ancestor
               is a backdrop root, so a transform here would kill any backdrop-filter nested
               below. (Note that this bar's OWN backdrop-blur is already a backdrop root for
               anything inside it — which is why the mobile menu above is opaque rather than
               frosted. Verified by measurement, not by eye.) */
            aria-label={label}
            className={`@container/yunui-nav fixed inset-x-0 mx-auto z-50 px-6 py-2.5 max-w-6xl w-[calc(100%-48px)] bg-background/80 backdrop-blur-xl border border-border rounded-full shadow-md flex items-center justify-between${className ? ` ${className}` : ""}`}
        >
            {/* Logo */}
            <Link href={homeHref} className="flex items-center gap-2 min-w-0 rounded-lg px-2 py-1 -mx-2 hover:bg-foreground/5 transition-colors duration-200">
                {brand ?? (
                    <>
                        <Image src={logoSrc} alt="" width={28} height={28} className="w-7 h-7 shrink-0" />
                        <span className="font-semibold text-sm tracking-tight truncate">{appName}</span>
                    </>
                )}
            </Link>

            {/* Nav Links */}
            {variant === "public" && (
                <div className="hidden @min-[720px]/yunui-nav:flex items-center gap-6 lg:gap-8 absolute left-1/2 -translate-x-1/2">
                    {links.map((link, index) => (
                        <Link
                            key={`${index}:${link.href}:${link.label}`}
                            href={link.href}
                            className="group relative px-2 lg:px-3 py-2 whitespace-nowrap min-w-15 text-center"
                        >
                            <span className={`text-sm relative z-10 ${isActive(link.href)
                                ? "text-foreground font-medium"
                                : "text-muted-foreground"
                                }`}>
                                {link.label}
                            </span>
                            <span className={`absolute bottom-1.5 left-1/2 -translate-x-1/2 h-0.5 bg-foreground rounded-full transition-all duration-200 yunui-accent-bg ${isActive(link.href) ? "w-8" : "w-0 group-hover:w-8"}`}></span>
                        </Link>
                    ))}
                </div>
            )}

            {/* Right Side. On mobile the bar keeps only theme + hamburger; the
                language switcher and auth buttons move into the menu so the bar
                never overflows / truncates the brand on a phone. */}
            <div className="flex items-center gap-1.5 shrink-0">
                {actions && <span className="hidden @min-[720px]/yunui-nav:flex items-center gap-1.5">{actions}</span>}
                {/* Only rendered when there is something to render: an empty flex
                    child still consumes one `gap-1.5`, which quietly shifted the
                    whole right cluster on hosts that pass no language switcher. */}
                {languageSwitcher && (
                    <span className="hidden @min-[720px]/yunui-nav:flex items-center gap-1.5">{languageSwitcher}</span>
                )}
                {themeToggle ?? <ThemeToggle variant="pill" />}

                {/* Account control, or the auth buttons when signed out. */}
                {variant !== "minimal" && account}
                {variant !== "minimal" && !account && (
                    <>
                        <Link
                            href={loginHref}
                            className="hidden @min-[720px]/yunui-nav:block text-sm text-muted-foreground hover:text-foreground transition-colors duration-200 py-2 whitespace-nowrap min-w-15 text-center"
                        >
                            {signIn}
                        </Link>
                        <Link
                            href={signupHref}
                            className="hidden @min-[720px]/yunui-nav:inline-block px-4 py-2 bg-foreground text-background text-sm font-medium rounded-lg hover:bg-foreground/90 hover:shadow-md transition-all duration-200 whitespace-nowrap min-w-20 text-center yunui-accent-bg yunui-accent-on"
                        >
                            {signUp}
                        </Link>
                    </>
                )}

                {/* Mobile menu toggle */}
                {variant === "public" && (
                    <button
                        type="button"
                        onClick={() => setMenuOpen((o) => !o)}
                        className="@min-[720px]/yunui-nav:hidden w-9 h-9 rounded-full flex items-center justify-center hover:bg-foreground/5 transition-colors"
                        aria-label={menuLabel}
                        aria-expanded={menuOpen}
                    >
                        {menuOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}
                    </button>
                )}
            </div>

            {/* Mobile menu */}
            {variant === "public" && menuOpen && (
                <>
                    <div className="@min-[720px]/yunui-nav:hidden fixed inset-0 -z-10" aria-hidden="true" onClick={() => setMenuOpen(false)} />
                    {/* Frosted glass, but at /95 not /85: the nav centers without a transform so the
                        blur works, yet over a same-toned page an 85% panel still read as see-through.
                        95% keeps the frost while making the menu opaque enough to not bleed content. */}
                    {/* Opaque, and with no `backdrop-blur`: this panel is nested inside a
                            nav that has its own `backdrop-filter`, which makes the nav a
                            BACKDROP ROOT — a nested backdrop-filter then samples an empty
                            backdrop and does exactly nothing. Measured: forcing the panel's
                            backdrop-filter to `none` produced a byte-identical screenshot,
                            while removing the NAV's changed it. So the blur here was never
                            real, and the 95% fill just let the page bleed through as
                            legible text behind the menu. */}
                        <div className="@min-[720px]/yunui-nav:hidden absolute top-full left-0 right-0 mt-3 p-2 bg-popover border border-border rounded-2xl shadow-lg shadow-black/5 flex flex-col gap-0.5">
                        {mobileMenuHeader}
                        {links.map((link, index) => (
                            <Link
                                key={`${index}:${link.href}:${link.label}`}
                                href={link.href}
                                onClick={() => setMenuOpen(false)}
                                className={`px-4 py-2.5 rounded-xl text-sm transition-colors hover:bg-foreground/5 ${isActive(link.href) ? "text-foreground font-medium" : "text-muted-foreground"}`}
                            >
                                {link.label}
                            </Link>
                        ))}
                        <div className="my-1 border-t border-border" />
                        {mobileMenuFooter ??
                            (languageSwitcher && (
                                <div className="px-2 py-1.5">{languageSwitcher}</div>
                            ))}
                        {!account && (
                            <>
                                <Link
                                    href={loginHref}
                                    onClick={() => setMenuOpen(false)}
                                    className="px-4 py-2.5 rounded-xl text-sm text-muted-foreground transition-colors hover:bg-foreground/5"
                                >
                                    {signIn}
                                </Link>
                                <Link
                                    href={signupHref}
                                    onClick={() => setMenuOpen(false)}
                                    className="mt-0.5 px-4 py-2.5 rounded-xl text-sm font-medium text-center bg-foreground text-background hover:bg-foreground/90 transition-colors yunui-accent-bg yunui-accent-on"
                                >
                                    {signUp}
                                </Link>
                            </>
                        )}
                    </div>
                </>
            )}
        </nav>
    );
}

export default Navbar;
